const item = $input.first().json;
const stdout = item.stdout || '';

let data;
try {
  data = JSON.parse(stdout);
} catch (e) {
  data = {
    sucesso: false,
    erro: 'Falha ao interpretar stdout do scraper Python',
    raw: stdout,
    stderr: item.stderr || ''
  };
}

if (!data.sucesso || !data.cupons || data.cupons.length === 0) {
  return [{
    json: {
      sucesso: false,
      mensagem: 'Nenhum cupom elegível extraído ou erro de sessão',
      detalhes: data,
      timestamp: new Date().toISOString()
    }
  }];
}

// Emite cada cupom elegível como um item independente
return data.cupons.map(cupom => ({
  json: {
    campanha_id: cupom.campanha_id,
    codigo: cupom.codigo,
    status: cupom.status,
    categoria_origem: cupom.categoria_origem,
    valor_desconto: cupom.valor_desconto,
    unidade: cupom.unidade,
    valor_maximo_desconto: cupom.valor_maximo_desconto,
    compra_minima: cupom.compra_minima,
    validade: cupom.validade,
    pode_ativar: cupom.pode_ativar,
    data_extracao: new Date().toISOString(),
    origem: 'scraper_ml_lote10'
  }
}));

const itens = $input.all();
const total = itens.length;
const primeiro = itens[0] ? itens[0].json : {};

if (primeiro.sucesso === false) {
  return [{
    json: {
      status: 'alerta',
      mensagem: primeiro.mensagem || 'Falha na extração',
      detalhes: primeiro.detalhes || {}
    }
  }];
}

return [{
  json: {
    status: 'sucesso',
    total_cupons_disponiveis: total,
    amostra_codigos: itens.map(i => i.json.codigo).slice(0, 10),
    timestamp: new Date().toISOString(),
    mensagem: `Lote de ${total} cupons extraído com sucesso. Pronto para validação e filtro por planilha.`
  }
}];

return [{
  json: {
    status: 'erro',
    motivo: 'Chave cookies-mercadolivre-cupons vazia ou inexistente no Redis',
    sugestao: 'Insira os cookies atualizados no Redis via redis-cli ou API antes da próxima rodada',
    timestamp: new Date().toISOString()
  }
}];
